"use client";
import { useState, useEffect } from 'react';
import { createClient } from '@supabase/supabase-js';
import { Lock, Download, Trophy, AlertOctagon, Landmark, PhoneCall, ArrowRight, CheckCircle2 } from 'lucide-react';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!, 
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);

/**
 * *************************************************************
 * PASTE YOUR ENTIRE BASE64 LOGO STRING BETWEEN THE QUOTES BELOW
 * *************************************************************
 */
const SCHOOL_LOGO_BASE64 = "data:image/png;base64,";

const getGrade = (mark: number) => {
  if (mark >= 70) return 'A';
  if (mark >= 60) return 'B';
  if (mark >= 50) return 'C';
  if (mark >= 45) return 'D';
  if (mark >= 40) return 'E';
  return 'U';
};

export default function GradesPage() {
  const [reports, setReports] = useState<any[]>([]);
  const [student, setStudent] = useState<any>(null);
  const [isLocked, setIsLocked] = useState(false);
  const [balance, setBalance] = useState(0);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const sessionData = localStorage.getItem('portalSession');
    if (sessionData) {
      const session = JSON.parse(sessionData);
      const s = session.student;
      if (s) {
        setStudent(s);
        const prevBal = Number(s.previous_balance) || 0;
        const fees = Number(s.term_1_fees) || 0;
        const paid = Number(s.term_1_paid) || 0;
        const totalBalance = (prevBal + fees) - paid;
        setBalance(totalBalance);

        // LOCKOUT LOGIC: Balance > $50 prevents data fetching
        if (totalBalance > 50) {
          setIsLocked(true);
          setLoading(false); 
        } else {
          fetchReports(s.id);
        }
      }
    } else {
      setLoading(false);
    }
  }, []);

  async function fetchReports(studentId: string) {
    try {
      const { data, error } = await supabase
        .from('results')
        .select('*')
        .eq('student_id', studentId.toUpperCase().trim())
        .order('year', { ascending: false })
        .order('term', { ascending: false });
      
      if (error) throw error;
      setReports(data || []);
    } catch (err) {
      console.error("Error fetching reports:", err);
    } finally {
      setLoading(false);
    }
  }

  const generatePDF = (report: any) => {
    const doc = new jsPDF();
    
    // 1. Header
    doc.setFillColor(15, 23, 42); 
    doc.rect(0, 0, 210, 45, 'F');
    
    if (SCHOOL_LOGO_BASE64.length > 100) {
        try {
            const imageType = SCHOOL_LOGO_BASE64.startsWith('data:image/jpeg') ? 'JPEG' : 'PNG';
            doc.addImage(SCHOOL_LOGO_BASE64, imageType, 15, 8, 28, 28);
        } catch (e) { console.error("Logo failed", e); }
    }

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.setFont("helvetica", "bold");
    doc.text("DETEMA SECONDARY SCHOOL", 105, 22, { align: "center" });
    doc.setFontSize(10);
    doc.text("Academic Excellence • Integrity • Leadership", 105, 30, { align: "center" });

    // 2. Student Details
    doc.setDrawColor(226, 232, 240);
    doc.setFillColor(248, 250, 252);
    doc.rect(15, 52, 180, 25, 'FD');
    doc.setTextColor(30, 41, 59);
    doc.text(`STUDENT: ${student?.name || 'N/A'}`, 20, 62);
    doc.text(`ID: ${student?.id || 'N/A'}`, 20, 70);
    doc.text(`TERM: ${report.term}`, 130, 62);
    doc.text(`YEAR: ${report.year}`, 130, 70);

    // 3. Process Subjects
    const subjectsList = Object.entries(report.subjects || {})
      .filter(([_, mark]) => mark !== null && mark !== "")
      .map(([subject, mark]) => {
        const score = Number(mark);
        return {
          name: subject.replace(/_/g, ' ').toUpperCase(),
          mark: score.toFixed(1),
          grade: getGrade(score),
          isFail: score < 50
        };
      });

    const passes = subjectsList.filter(s => ['A', 'B', 'C'].includes(s.grade)).length;

    // 4. Results Table with Highlighting
    autoTable(doc, {
      startY: 85,
      head: [['SUBJECT', 'SCORE (%)', 'GRADE']],
      body: subjectsList.map(s => [s.name, s.mark, s.grade]),
      theme: 'grid',
      headStyles: { fillColor: [37, 99, 235] },
      didParseCell: (data) => {
        const rowIndex = data.row.index;
        if (data.section === 'body' && subjectsList[rowIndex].isFail) {
          data.cell.styles.textColor = [220, 38, 38]; // Red for marks < 50%
          data.cell.styles.fontStyle = 'bold';
        }
      }
    });

    // 5. Summary Footer
    const finalY = (doc as any).lastAutoTable.finalY + 15;
    doc.setFillColor(241, 245, 249);
    doc.rect(15, finalY, 180, 20, 'F');
    doc.setTextColor(15, 23, 42);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.text(`SUBJECTS PASSED (Grade C or Better): ${passes} / ${subjectsList.length}`, 105, finalY + 12, { align: 'center' });

    doc.save(`${student?.name}_T${report.term}_${report.year}.pdf`);
  };

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 font-black text-slate-400 animate-pulse uppercase">
      Loading Records...
    </div>
  );

  if (isLocked) {
    return (
      <div className="max-w-4xl mx-auto p-6 md:p-12">
        <div className="bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-slate-100">
          <div className="bg-red-600 p-10 text-white text-center">
            <Lock size={40} className="mx-auto mb-6" />
            <h1 className="text-4xl font-black uppercase italic tracking-tighter mb-2">Portal Locked</h1>
            <p className="text-red-100 font-bold uppercase tracking-widest text-sm">Outstanding Fees Detected</p>
          </div>
          <div className="p-8 md:p-12 text-center space-y-8">
            <div>
                <h2 className="text-2xl font-black text-slate-900 mb-2 uppercase italic">Payment Required</h2>
                <p className="text-slate-600 font-medium">Clear your balance to unlock academic transcripts.</p>
                <div className="mt-6 inline-block bg-red-50 px-8 py-4 rounded-2xl border border-red-100">
                    <p className="text-[10px] font-black text-red-400 uppercase tracking-widest mb-1">Total Owed</p>
                    <p className="text-3xl font-black text-red-600">${balance.toFixed(2)}</p>
                </div>
            </div>
            <div className="grid md:grid-cols-2 gap-6">
                <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 flex flex-col items-center">
                    <Landmark size={24} className="mb-3 text-slate-900" />
                    <span className="text-xs font-bold uppercase">1. Pay at Accounts Office</span>
                </div>
                <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 flex flex-col items-center">
                    <PhoneCall size={24} className="mb-3 text-slate-900" />
                    <span className="text-xs font-bold uppercase">2. Confirm with Finance</span>
                </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto p-4 md:p-8 space-y-8">
      <div className="bg-slate-900 rounded-[2rem] p-10 text-white shadow-2xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div>
          <h1 className="text-4xl font-black italic uppercase tracking-tighter">Academic Portal</h1>
          <p className="text-blue-400 font-bold uppercase tracking-[0.2em] mt-2">{student?.name}</p>
        </div>
        <Trophy size={60} className="text-blue-500/20" />
      </div>

      <div className="grid gap-6">
        {reports.map((report, i) => {
            const subjectsList = Object.entries(report.subjects || {}).filter(([_, m]) => m !== "");
            const passCount = subjectsList.filter(([_, m]) => Number(m) >= 50).length;
            
            return (
                <div key={i} className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden group">
                    <div className="p-8 bg-slate-50 flex flex-col md:flex-row justify-between items-center gap-6">
                        <div className="flex items-center gap-4">
                            <div className="w-14 h-14 rounded-2xl bg-blue-600 text-white flex items-center justify-center font-black text-xl italic">T{report.term}</div>
                            <div>
                                <h3 className="text-xl font-black uppercase italic">Year {report.year} Results</h3>
                                <div className="flex items-center gap-2 text-emerald-600">
                                    <CheckCircle2 size={14} />
                                    <span className="text-[10px] font-bold uppercase tracking-wider">{passCount} Subjects Passed</span>
                                </div>
                            </div>
                        </div>
                        <button 
                            onClick={() => generatePDF(report)}
                            className="bg-slate-900 hover:bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center gap-3 transition-all active:scale-95 shadow-lg"
                        >
                            <Download size={16} /> Download PDF
                        </button>
                    </div>
                </div>
            )
        })}
      </div>
    </div>
  );
}